// Reconstructed from the deployed bytecode. Same behaviour, not the attackers' source.
contract C {
    address public owner;
    mapping(bytes32 => string) private urls;

    event UrlSet(bytes32 indexed key, string url);

    function set(bytes32 key, string calldata url) external {
        require(msg.sender == owner);
        urls[key] = url;
        emit UrlSet(key, url);
    }

    function get(bytes32 key) external view returns (string memory) {
        return urls[key];
    }

    // plus owner(), transferOwnership(address) and its event
}
